/* ---------- BUILD IT DIFFERENT WAYS (class worksheet 11/11: hundreds, tens, ones with snap cubes) ---------- */
const hw = (n: number) => (n === 1 ? "hundred" : "hundreds"), tw = (n: number) => (n === 1 ? "ten" : "tens"), ow = (n: number) => (n === 1 ? "one" : "ones");
const way = (a: number, b: number, c: number) => `${a} ${hw(a)}, ${b} ${tw(b)}, ${c} ${ow(c)}`;
const parts = (a: number, b: number, c: number) => { const p = [a * 100, b * 10, c].filter((x) => x > 0); return p.length ? p.join(" plus ") : "0"; };
const BL = (h: number, t: number, o: number) => ({ k: "blocks", h, t, o });
const bSteps = (n: number) => { const [h, t, o] = dig(n); return {
  a: { t: `${n} = ${way(h, t, o)}`, say: `${n} is ${h} ${hw(h)}, ${t} ${tw(t)}, and ${o} ${ow(o)}.`, v: BL(h, t, o) },
  b: { t: "Decompose: trade 1 hundred → 10 tens", say: `Trade 1 hundred for 10 tens. The hundred goes away, and 10 tens take its place. Now there ${h - 1 === 1 ? "is" : "are"} ${h - 1} ${hw(h - 1)}.`, v: BL(h - 1, t + 10, o) },
  c: { t: `${t} tens + 10 tens = ${t + 10} tens`, say: `Count the tens. ${t} ${tw(t)} plus 10 more tens makes ${t + 10} tens.`, v: BL(h - 1, t + 10, o) },
  d: { t: `${parts(h - 1, t + 10, o).replace(/ plus /g, " + ")} = ${n} ✓`, say: `Add it back up. ${parts(h - 1, t + 10, o)} is ${n}. It still makes ${n}!`, v: BL(h - 1, t + 10, o) },
  w2: { t: `${h} hundreds → ${h * 10} tens`, say: `Trade all ${h} hundreds for ${h * 10} tens. ${h * 10} tens plus ${t} ${tw(t)} makes ${h * 10 + t} tens.`, v: BL(0, h * 10 + t, o) },
  t1: { t: "Decompose: trade 1 ten → 10 ones", say: `Trade 1 ten for 10 ones. Now there are ${t - 1} ${tw(t - 1)} and ${o + 10} ones.`, v: BL(h, t - 1, o + 10) },
  t2: { t: "Trade 1 ten → 10 ones", say: `Now trade 1 ten for 10 ones. That makes ${h * 10 + t - 1} tens and ${o + 10} ones.`, v: BL(0, h * 10 + t - 1, o + 10) },
  t3: { t: `${parts(h, t - 1, o + 10).replace(/ plus /g, " + ")} = ${n} ✓`, say: `Add it back up. ${parts(h, t - 1, o + 10)} is ${n}. It still makes ${n}!`, v: BL(h, t - 1, o + 10) },
  w4: { t: `${n} ones`, say: `You can even trade everything for ones. ${n} ones still makes ${n}.`, v: BL(0, 0, n) },
  chk: { t: "Add it back up ✓", say: `Check every row. Add it back up. Does it still make ${n}? Then it is right!` },
}; };
const BN = [235, 154, 219, 197, 256]; while (BN.length < (FULL ? 36 : 20)) { const n = r(1, 3) * 100 + r(1, 9) * 10 + r(1, 9); if (!BN.includes(n)) BN.push(n); }
type Row = { g: (number | null)[]; exact?: boolean };
BN.forEach((n, i) => { const [h, t, o] = dig(n); const S = bSteps(n);
  const ws = i < 5 || i % 3 === 0, single = i < 5 || i % 3 !== 0;
  if (ws) { const rows: Row[] = [{ g: [null, null, null] }, { g: [null, null, o] }, h >= 2 ? { g: [0, null, null] } : { g: [null, t + 9, null] }, { g: [0, 0, null] }];
    const sol = [[h, t, o], [h - 1, t + 10, o], h >= 2 ? [0, h * 10 + t, o] : [0, t + 9, o + 10], [0, 0, n]];
    add({ sk: "bld", kind: "build", n, rows, sol, txt: `Show ${n} 4 different ways using hundreds, tens, and ones.`, say: `Show ${n} 4 different ways using hundreds, tens, and ones.`, ans: sol.map((s) => s.join("|")).join(","), v: BL(h, t, o), steps: [S.a, S.b, S.c, h >= 2 ? S.w2 : S.t2, S.w4, S.chk] }); }
  if (single) { const tenT = i % 2 === 1 && i >= 5;
    if (tenT) add({ sk: "bld", kind: "build", n, rows: [{ g: [null, null, null], exact: true }], sol: [[h, t - 1, o + 10]], txt: `Trade 1 ten for 10 ones. Fill in the new way to show ${n}.`, say: `Trade 1 ten for 10 ones. Fill in the new way to show ${n}.`, ans: [h, t - 1, o + 10].join("|"), v: BL(h, t, o), steps: [S.a, S.t1, S.t3] });
    else add({ sk: "bld", kind: "build", n, rows: [{ g: [null, null, null], exact: true }], sol: [[h - 1, t + 10, o]], txt: `Trade 1 hundred for 10 tens. Fill in the new way to show ${n}.`, say: `Trade 1 hundred for 10 tens. Fill in the new way to show ${n}.`, ans: [h - 1, t + 10, o].join("|"), v: BL(h, t, o), steps: [S.a, S.b, S.c, S.d] }); }
  // multiple choice: wrong options are her real mistakes
  const right = way(h - 1, t + 10, o), kept = way(h, t + 10, o), off = way(h - 1, t + 10 + (i % 2 ? 3 : -2), o), drop = way(h - 1, t, o);
  const err: Record<string, string> = { [kept]: "kept", [off]: "tens", [drop]: "drop" };
  add({ sk: "bld", kind: "mc", n, txt: `Which is another way to show ${n}?`, say: `Which is another way to show ${n}?`, v: BL(h, t, o), ch: opts(right, [kept, off, drop]), err, ans: right, steps: [S.a, S.b, S.c, S.d] });
  if (i % 2 === 0 || i < 5) { const nm = NAMES[1 + (i % 7)]; const tooMany = i % 4 === 2;
    const sh = tooMany ? [h - 1, t + 13, o] : [h, t + 10, o]; const tot = sh[0] * 100 + sh[1] * 10 + sh[2];
    const A = tooMany ? "She counted too many tens." : "She kept the hundred after trading it.";
    const ch = opts(A, ["Nothing. It is right.", tooMany ? "She kept the hundred after trading it." : "She counted too many tens.", "She forgot the ones."]);
    add({ sk: "bld", kind: "mc", n, txt: `${nm} showed ${n} as ${way(sh[0], sh[1], sh[2])}. What went wrong?`, say: `${nm} showed ${n} as ${sh[0]} ${hw(sh[0])}, ${sh[1]} tens, and ${sh[2]} ${ow(sh[2])}. What went wrong?`, v: BL(sh[0], sh[1], sh[2]), ch, err: { "Nothing. It is right.": "nocheck", "She kept the hundred after trading it.": "kept", "She counted too many tens.": "tens" }, ans: A,
      steps: [{ t: `${parts(sh[0], sh[1], sh[2]).replace(/ plus /g, " + ")} = ${tot}`, say: `Add it back up. ${parts(sh[0], sh[1], sh[2])} is ${tot}, not ${n}.`, v: BL(sh[0], sh[1], sh[2]) },
        tooMany ? { t: `${t + 13} tens is too many`, say: `Count the tens again. 1 hundred becomes 10 tens, so there should be ${t + 10} tens, not ${t + 13}.`, v: BL(h - 1, t + 10, o) } : { t: "Take the hundred away!", say: `When you trade 1 hundred for 10 tens, take the hundred away. Don't keep it!`, v: BL(h - 1, t + 10, o) },
        { t: `So: ${A}`, say: `So the answer is: ${A}` }] }); }
});

const fix = (s: string) => s.replace(/\b1 (ones|tens|hundreds)\b/g, (_m, p) => "1 " + p.slice(0, -1));
for (const q of BANK) { q.txt = fix(q.txt); if (q.say) q.say = fix(q.say); q.steps.forEach((st) => { st.t = fix(st.t); st.say = fix(st.say); }); if (q.ch) q.ch = q.ch.map(fix); q.ans = fix(q.ans); }
